"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-0299-01-01:0":{"b": ["Mbretëria e Kushit — periudha e Meroes: fillon", "ee436c47"], "d": ["Periudha e Meroes, që fillon me zhvendosjen e qendrës së Kushit nga Napata në Meroe (rreth 300 p.e.s.) dhe shtrihet deri në vitin 350 e.s.", "5c13abcf"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-1069-01-01:0":{"b": ["Mbretëria e Kushit — periudha e Napatës: fillon", "fd21e916"], "d": ["Periudha e dinastisë së Kushit me qendër Napatën; qendra zhvendoset në Meroe ~300 p.e.s. Dinastia XXV (Kush), që pushtoi Egjiptin, i përket kësaj periudhe — datat e Dinastisë XXV NUK gjenden në këtë burim.", "b8938f36"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-1449-01-01:0":{"b": ["Mbretëria/kultura e Kermës (Kush): merr fund", "95c2812c"], "d": ["Mbretëri nubiane me qendër Kermën, poshtë Kataraktit të Tretë; kalon fazat e Kermës së Vjetër (~2500), të Mesme dhe Klasike dhe merr fund ~1450 p.e.s. Honegger 2005: vendbanim i rrethuar 'Kerma Classique (vers 1500 av. J.-C.)'.", "5ea1ab25"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-1499-01-01:0":{"b": ["Napata (Xhebel Barkal): fillon", "fbf16715"], "d": ["U themelua si post i fortifikuar i Egjiptit në Mbretërinë e Re; ishte qyteti kryesor i dinastisë së Kushit (periudha e Napatës 1070–300 p.e.s.) dhe e ruajti rëndësinë gjatë periudhës së Meroes (300 p.e.s.–350 e.s.).", "a384d267"]},
