"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-1811-01-01:0":{"b": ["Mbretëria e Mesme: merr fund", "51fa178c"], "d": ["Periudha e dytë e madhe e bashkimit të Egjiptit; artikulli mbështet kronologjinë 'High' (Low hidhet poshtë), periudha e Senusretit III është matur me unazat e trarëve të kështjellës së Uronartit (Sudan).", "e792785c"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-2050-01-01:0":{"b": ["Periudha e Parë Ndërmjetëse: merr fund", "7e2d8fc1"], "d": ["Periudha e copëtuar që zgjat nga shpërbërja e autoritetit qendror të Mbretërisë së Vjetër deri në fillimin e Mbretërisë së Mesme; artikulli nënvizon përputhjen me ngjarjen e thatësirës 4.2 ka (rreth 2250 p.e.s.).", "47a3a1aa"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-2050-01-01:1":{"b": ["Mbretëria e Mesme: fillon", "0e85ade1"], "d": ["Periudha e dytë e madhe e bashkimit të Egjiptit; artikulli mbështet kronologjinë 'High' (Low hidhet poshtë), periudha e Senusretit III është matur me unazat e trarëve të kështjellës së Uronartit (Sudan).", "e792785c"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-2242-01-01:0":{"b": ["Mbretëria e Vjetër (Epoka e Piramidave): merr fund", "65237d84"], "d": ["Mbretëria e Epokës së Piramidave; sipas Erdil et al. 2025, fillimi i MV është ~2698–2629 p.e.s. (95%), kalimi te Periudha e Parë Ndërmjetëse ~2283–2204 p.e.s. (95%). Kronologjia 'Low' në këtë interval nuk mbështetet më.", "2ac5035a"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-2242-01-01:1":{"b": ["Periudha e Parë Ndërmjetëse: fillon", "ef148434"], "d": ["Periudha e copëtuar që zgjat nga shpërbërja e autoritetit qendror të Mbretërisë së Vjetër deri në fillimin e Mbretërisë së Mesme; artikulli nënvizon përputhjen me ngjarjen e thatësirës 4.2 ka (rreth 2250 p.e.s.).", "47a3a1aa"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-2499-01-01:0":{"b": ["Mbretëria/kultura e Kermës (Kush): fillon", "f7cdc981"], "d": ["Mbretëri nubiane me qendër Kermën, poshtë Kataraktit të Tretë; kalon fazat e Kermës së Vjetër (~2500), të Mesme dhe Klasike dhe merr fund ~1450 p.e.s. Honegger 2005: vendbanim i rrethuar 'Kerma Classique (vers 1500 av. J.-C.)'.", "5ea1ab25"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-2662-01-01:0":{"b": ["Mbretëria e Vjetër (Epoka e Piramidave): fillon", "9e3a1499"], "d": ["Mbretëria e Epokës së Piramidave; sipas Erdil et al. 2025, fillimi i MV është ~2698–2629 p.e.s. (95%), kalimi te Periudha e Parë Ndërmjetëse ~2283–2204 p.e.s. (95%). Kronologjia 'Low' në këtë interval nuk mbështetet më.", "2ac5035a"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-3125-01-01:0":{"b": ["Kultura Nakada (Naqada): merr fund", "a6d98d7b"], "d": ["Kultura predinastike e Egjiptit të Epërm pas Badarit; përfshin fazat Naqada I-III, dhe në Naqada IIIC me Dinastinë I (Aha) arrihet bashkimi politik.", "8fadb99a"]},
