"OLAYLAR_ARKEOLOJI_PILOT:-7999-01-01:0":{"b": ["Göbekli Tepe braktiset (pas PPNB-së së mesme)", "1629134f"], "d": ["Sipas majave të shigjetave, vendi u braktis pas PPNB-së së mesme; burimi nuk jep interval të kalibruar.", "1b42db4d"]},
"OLAYLAR_ARKEOLOJI_PILOT:-9299-01-01:0":{"b": ["Jeriko (Tell es-Sultan): fillojnë datat radiokarbonike të shtresës më të hershme PPN (Stage IV/IVA)", "5ea619fa"], "d": ["Gjurmët natufiane janë më të vjetra (në të njëjtën faqe kalibrimi «11170–10980 BC» është i paqartë); datat e shtresës së ngulitur PPN fillojnë në 9300 p.e.s.", "15c5503b"]},
"OLAYLAR_ARKEOLOJI_PILOT:-9528-01-01:0":{"b": ["Göbekli Tepe: data e suvasë së mureve të Rrethit D (Shtresa III) — prova e datuar e ndërtimit monumental", "4354b424"], "d": ["Mostra më e drejtpërdrejtë e datueshme e ndërtesave rrethore me shtylla në formë T (Shtresa III, PPNA) është suvaja e mureve; mostrat e mbushjes janë vetëm kufiri i poshtëm pas shkatërrimit.", "77cb01da"]},
"OLAYLAR_ARKEOLOJI_ZINCIR:-0026-01-01:0":{"b": ["Roma, Aleksandria: Republika Romake → interval pa zotërues", "7df67fb7"], "d": ["Në pikat Roma, Aleksandri zotërimi kalon nga Republika Romake te intervali pa zotërues. Të dhënat e burimit për kalimin: vdekja e Teodosit, 17 janar 395 (konsullata e Olibrit dhe Probit): Sokrat Skolastiku, Hist. Kish. 5.26 (NPNF, newadvent.org/fathers/26015.htm); Marcellinus Comes s.a. 395: Arkadi dhe Honori e trashëgojnë perandorinë të ndarë vetëm sipas selive të tyre.", "5b0ba108"]},
"OLAYLAR_ARKEOLOJI_ZINCIR:-0048-01-01:0":{"b": ["Marseja, Massalia: Massalia (Marsejë) → Republika Romake", "a9950655"], "d": ["Në pikat Marsejë, Massalia zotërimi kalon nga Massalia (Marsejë) te Republika Romake. Të dhënat e burimit për kalimin: Cezari BC 2.22: pasi qyteti u mund, u la 'conservans' dhe një garnizon — fundi i statusit të aleatit të lirë, kontrolli romak.", "51e72f2c"]},
"OLAYLAR_ARKEOLOJI_ZINCIR:-0085-01-01:0":{"b": ["Athinë: Fillon periudha e Republikës Romake", "86f10b7f"], "d": ["Athinë: Fillon periudha e Republikës Romake. Kjo datë nuk është ngjarje më vete, ajo tregon fillimin e kësaj periudhe; hollësitë dhe burimet janë më poshtë.", "deee676b"]},
