"OLAYLAR_ARKEOLOJI_ZINCIR:-0112-01-01:0":{"b": ["Dura-Europos: Perandoria Seleukide → Perandoria Parte (Arsakide)", "3880f69a"], "d": ["Në pikat Dura-Europos zotërimi kalon nga Perandoria Seleukide te Perandoria Parte (Arsakide). Të dhënat e burimit për kalimin: pushtimi part (rreth 113) | Burimi: Leriche, P. & MacKenzie, D. N., \"Dura Europos\", Encyclopaedia Iranica VII/6, 1996 (rev. 2011); data e themelimit nga përmbledhja e Leriche-it (pasqyra kavehfarrokh.com) | https://web.archive.org/web/2025/https://www.iranicaonline.org/articles/dura-europos | «Dura Europos was brought into the Iranian cultural sphere after the Parthian conquest in about 113 B.C.E.»", "100bc82e"]},
"OLAYLAR_ARKEOLOJI_ZINCIR:-0120-01-01:0":{"b": ["Zhangye (Ganzhou): Fillon periudha e Dinastisë Han Perëndimore", "811aa11b"], "d": ["Zhangye (Ganzhou): Fillon periudha e Dinastisë Han Perëndimore. Kjo datë nuk është ngjarje më vete, ajo tregon fillimin e kësaj periudhe; hollësitë dhe burimet janë më poshtë.", "95a1a2d7"]},
"OLAYLAR_ARKEOLOJI_ZINCIR:-0131-01-01:0":{"b": ["Urfa (Edesa / Orhai / Vodina): Fillon periudha e Mbretërisë së Osroenës (Edesës)", "2f4410d7"], "d": ["Urfa (Edesa / Orhai / Vodina): Fillon periudha e Mbretërisë së Osroenës (Edesës). Kjo datë nuk është ngjarje më vete, ajo tregon fillimin e kësaj periudhe; hollësitë dhe burimet janë më poshtë.", "5e9c1853"]},
"OLAYLAR_ARKEOLOJI_ZINCIR:-0132-01-01:0":{"b": ["Pergami, Pergamon: Mbretëria e Pergamit (Atalide) → Republika Romake", "164fbaa9"], "d": ["Në pikat Pergam, Pergamon zotërimi kalon nga Mbretëria e Pergamit (Atalide) te Republika Romake. Të dhënat e burimit për kalimin: Straboni 13.4.2: 'The Romans proclaimed the country a province, calling it Asia'.", "1e50d81c"]},
"OLAYLAR_ARKEOLOJI_ZINCIR:-0140-01-01:0":{"b": ["Babilonia, Seleukia (mbi Tigër), Uruku: Perandoria Seleukide → Perandoria Parte (Arsakide)", "433bc35b"], "d": ["Në pikat Babiloni, Seleuki (mbi Tigër), Uruk zotërimi kalon nga Perandoria Seleukide te Perandoria Parte (Arsakide). Të dhënat e burimit për kalimin: Mitridati I arrin në Seleuki në korrik 141 dhe në Uruk në tetor 141 | Burimi: Lendering, J., Livius.org: Mithradates I (faqja Bagayasha); fusnota: van der Spek 1997/8: 171 | https://livius.org/articles/person/bagayasha | «In July 141, he captured Seleucia and in October he reached Uruk in southern Babylonia.»", "7c37e7d7"]},
"OLAYLAR_ARKEOLOJI_ZINCIR:-0145-01-01:0":{"b": ["Korinti: Merr fund periudha e Korintit", "0d4e1ef0"], "d": ["Korinti: Merr fund periudha e Korintit. Kjo datë nuk është ngjarje më vete, ajo tregon fundin e kësaj periudhe; hollësitë dhe burimet janë më poshtë.", "e713b7bd"]},
"OLAYLAR_ARKEOLOJI_ZINCIR:-0147-01-01:0":{"b": ["Ekbatana, Hamadani: Perandoria Seleukide → Perandoria Parte (Arsakide)", "3ceabd91"], "d": ["Në pikat Ekbatana, Hamadan zotërimi kalon nga Perandoria Seleukide te Perandoria Parte (Arsakide). Të dhënat e burimit për kalimin: Mitridati I pushton Medinë (148; sipas përcjelljes së Justinit 41.6.7) | Burimi: Lendering, J., Livius.org: Mithradates I (faqja Bagayasha); fusnota: van der Spek 1997/8: 171 | https://livius.org/articles/person/bagayasha | «Mithradates conquered Media in 148 BCE and appointed Bacasis as governor»", "a34a4560"]},
"OLAYLAR_ARKEOLOJI_ZINCIR:-0167-01-01:0":{"b": ["Petra: Fillon periudha e Mbretërisë Nabatease", "3788a3eb"], "d": ["Petra: Fillon periudha e Mbretërisë Nabatease. Kjo datë nuk është ngjarje më vete, ajo tregon fillimin e kësaj periudhe; hollësitë dhe burimet janë më poshtë.", "14739f47"]},
